import{_ as r,C as s,o as t,c as n,a2 as a,b as l,w as i,a as d,E as c,a3 as h}from"./chunks/framework.Brv5O9VI.js";const v=JSON.parse('{"title":"14.2 Architecture Styles: Modular Monolith vs Microservices","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.2-architecture-styles.md","filePath":"system-design/14.2-architecture-styles.md"}'),u={name:"system-design/14.2-architecture-styles.md"};function g(p,e,m,y,f,b){const o=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="_14-2-architecture-styles-modular-monolith-vs-microservices" tabindex="-1">14.2 Architecture Styles: Modular Monolith vs Microservices <a class="header-anchor" href="#_14-2-architecture-styles-modular-monolith-vs-microservices" aria-label="Permalink to &quot;14.2 Architecture Styles: Modular Monolith vs Microservices&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>An architecture style defines how the software boundaries, execution processes, and communication interfaces are organized—ranging from single self-contained monoliths to distributed microservices and serverless functions.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><p>The backend is built as a <strong>Modular Monolith</strong> ([<code>app.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py)):</p><ul><li><strong>Module Separation</strong>: Clear internal domain boundaries: <ul><li>Vector search &amp; embedding in <code>app.py</code></li><li>Domain guardrailing in [<code>guardrail.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/guardrail.py)</li><li>Statutory gap evaluation &amp; CSV formatting in [<code>gap_engine.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/gap_engine.py)</li></ul></li><li><strong>Single Process Execution</strong>: All modules run in the same Python runtime, communicating via native in-memory function calls with zero network serialization overhead.</li></ul>',7)),(t(),l(h,null,{default:i(()=>[c(o,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Monolith%5B%22Modular%20Monolith%20Execution%20Process%20(FastAPI)%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20subgraph%20WebModule%5B%22Web%20%26%20Transport%20Module%20(app.py)%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20Routes%5B%22%2Fchat%2C%20%2Faudit%2Fexport%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20Pydantic%5B%22Schema%20Deserializer%22%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20subgraph%20MLModule%5B%22Inference%20Module%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20FastEmbed%5B%22FastEmbed%20ONNX%20Engine%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20FAISS%5B%22FAISS%20IndexFlatIP%20(C%2B%2B%20RAM)%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20SKLearn%5B%22Scikit-Learn%20Classifier%22%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20subgraph%20RulesModule%5B%22Regulatory%20Business%20Logic%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20Guard%5B%22guardrail.py%20(4-Tier%20Rules)%22%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20Gap%5B%22gap_engine.py%20(Scheme-I%20%26%20AIS-037)%22%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20%0A%20%20%20%20%20%20%20%20Routes%20--%3E%20Pydantic%0A%20%20%20%20%20%20%20%20Pydantic%20--%3E%20FastEmbed%0A%20%20%20%20%20%20%20%20FastEmbed%20--%3E%20FAISS%0A%20%20%20%20%20%20%20%20Pydantic%20--%3E%20SKLearn%0A%20%20%20%20%20%20%20%20FAISS%20--%3E%20Guard%0A%20%20%20%20%20%20%20%20Guard%20--%3E%20Gap%0A%20%20%20%20end%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-full-comparison-with-alternatives" tabindex="-1">3. Full Comparison with Alternatives <a class="header-anchor" href="#_3-full-comparison-with-alternatives" aria-label="Permalink to &quot;3. Full Comparison with Alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Architectural Pattern</th><th style="text-align:left;">Communication Overhead</th><th style="text-align:left;">Operational Complexity</th><th style="text-align:left;">Hardware Cost</th><th style="text-align:left;">Failure Isolation</th><th style="text-align:left;">Fit for This Engine</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Modular Monolith</strong> (Used)</td><td style="text-align:left;"><strong>Zero (In-Memory Pointers)</strong></td><td style="text-align:left;"><strong>Very Low (1 Docker container)</strong></td><td style="text-align:left;"><strong>Minimal (~65 MB RAM)</strong></td><td style="text-align:left;">Single Process Boundary</td><td style="text-align:left;"><strong>Optimal</strong></td></tr><tr><td style="text-align:left;"><strong>Microservices</strong></td><td style="text-align:left;">High (gRPC/HTTP 10-25ms)</td><td style="text-align:left;">High (Kubernetes, Service Mesh)</td><td style="text-align:left;">High ($150+/mo)</td><td style="text-align:left;">High per service</td><td style="text-align:left;">Overkill for 3 endpoints</td></tr><tr><td style="text-align:left;"><strong>Serverless (AWS Lambda)</strong></td><td style="text-align:left;">Moderate (Cold starts 2-5s)</td><td style="text-align:left;">Moderate (CloudWatch, IAM)</td><td style="text-align:left;">Variable</td><td style="text-align:left;">High</td><td style="text-align:left;">Poor (Cold starts break vector index)</td></tr><tr><td style="text-align:left;"><strong>Event-Driven CQRS</strong></td><td style="text-align:left;">High (Kafka/RabbitMQ broker)</td><td style="text-align:left;">Very High</td><td style="text-align:left;">High</td><td style="text-align:left;">High</td><td style="text-align:left;">Overkill (No writes/mutations)</td></tr></tbody></table><h3 id="why-we-did-not-choose-microservices" tabindex="-1">Why We Did NOT Choose Microservices: <a class="header-anchor" href="#why-we-did-not-choose-microservices" aria-label="Permalink to &quot;Why We Did NOT Choose Microservices:&quot;">​</a></h3><p>Splitting this 3-endpoint service into separate &quot;Embedding Service&quot;, &quot;Guardrail Service&quot;, and &quot;Gap Service&quot; would add 10-20ms of network serialization latency across internal hops, transforming a sub-18ms local response into an 80ms multi-hop distributed system without providing any scaling benefit [CONFIRM WITH DEVELOPER].</p><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Coupled Deployment</strong>: Updating a single regular expression in <code>guardrail.py</code> requires restarting the entire FastAPI container, reloading the ONNX model into RAM.</li><li><strong>Resource Coupling</strong>: CPU-intensive vector embedding competes with web socket I/O on the same machine.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Remains stable; handled cleanly by adding Uvicorn workers.</li><li><strong>At 100x Load</strong>: CPU saturation during ONNX embedding slows down HTTP response times for all modules.</li><li><strong>At 1000x Load</strong>: The monolith must be decoupled: split the computationally heavy FastEmbed inference into a dedicated GPU/ONNX worker cluster, while keeping the lightweight web controllers and gap rules as a stateless API gateway.</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><p>When traffic exceeds 500 RPS, separate into two distinct deployables:</p><ol><li><strong>API Gateway &amp; Rule Service</strong> (Node.js or Go): Handles client sockets, auth, rate limiting, and rule validation.</li><li><strong>Dense Vector Inference Microservice</strong> (Python/Triton): Dedicated embedding and FAISS search over high-speed gRPC.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;We intentionally structured our backend as a Modular Monolith. Co-locating our FastEmbed ONNX model, FAISS index, and gap rules in a single process eliminates network hops and allows zero-copy in-memory pointer sharing, keeping total query latency under eighteen milliseconds with minimal operational complexity.&quot;</p></blockquote>',18))])}const x=r(u,[["render",g]]);export{v as __pageData,x as default};
